-- T-016 (migration 0010; TEST-012, TEST-029; D-009, D-035, D-037, D-043,
-- D-044): an import's upload never changes, for any role; its profile is
-- written once, by its job, and is there exactly when the import is past
-- profiling; the API never writes a profile, a preview or an error report;
-- an error report is named all or nothing; FAILED and COMMITTED imports are
-- final; only the API, the worker and the schema owner write imports.
-- Disposable dt_test_* database only (scripts/run_db_tests.sh). One
-- transaction, rolled back. Generated by scripts/render_db_tests.py.
\set ON_ERROR_STOP 1
BEGIN;
CREATE FUNCTION pg_temp.fail(msg text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  IF current_setting('dt.collect', true) = 'on' THEN RAISE WARNING 'FAILED: %', msg;
  ELSE RAISE EXCEPTION 'FAILED: %', msg; END IF;
END $$;
CREATE FUNCTION pg_temp.must_fail(stmt text, state text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE got text; msg text;
BEGIN
  BEGIN
    EXECUTE stmt;
    RAISE EXCEPTION USING ERRCODE = 'P0099'; -- roll the unexpected success back
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE; msg := SQLERRM;
  END;
  IF got = 'P0099' THEN
    PERFORM pg_temp.fail(format('expected SQLSTATE %s but the statement succeeded: %s', state, stmt));
  ELSIF got <> state THEN
    PERFORM pg_temp.fail(format('expected SQLSTATE %s but got %s (%s) for: %s', state, got, msg, stmt));
  END IF;
END $$;
CREATE FUNCTION pg_temp.check(ok boolean, what text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  IF ok IS NOT TRUE THEN PERFORM pg_temp.fail(what); END IF;
END $$;
-- An UPDATE of one import of tenant A, as a statement for must_fail.
CREATE FUNCTION pg_temp.upd(imp text, change text) RETURNS text LANGUAGE sql AS $$
  SELECT format('UPDATE twin.imports SET %s WHERE organization_id=%L AND id=%L', change, 'org_01M4YDQK00TA00000000000000', imp)
$$;
GRANT EXECUTE ON FUNCTION pg_temp.upd(text, text) TO PUBLIC;

SET LOCAL ROLE twin_owner;
SELECT set_config('app.oidc_issuer','https://test.invalid',true), set_config('app.oidc_subject','subject_a',true),
       set_config('app.organization_id','org_01M4YDQK00TA00000000000000',true), set_config('app.user_id','usr_01M4YDQK00TA00000000000001',true);
INSERT INTO twin.users(id,oidc_issuer,oidc_subject) VALUES ('usr_01M4YDQK00TA00000000000001','https://test.invalid','subject_a');
INSERT INTO twin.organizations(id,organization_id,name) VALUES ('org_01M4YDQK00TA00000000000000','org_01M4YDQK00TA00000000000000','Tenant A');
INSERT INTO twin.memberships(organization_id,user_id,role) VALUES ('org_01M4YDQK00TA00000000000000','usr_01M4YDQK00TA00000000000001','owner');
INSERT INTO twin.projects(id,organization_id,name,created_by) VALUES ('prj_01M4YDQK00TA00000000000001','org_01M4YDQK00TA00000000000000','Project A','usr_01M4YDQK00TA00000000000001');
INSERT INTO twin.models(id,organization_id,project_id,name,domain,created_by)
  VALUES ('mdl_01M4YDQK00TA00000000000001','org_01M4YDQK00TA00000000000000','prj_01M4YDQK00TA00000000000001','Model A','software_delivery','usr_01M4YDQK00TA00000000000001');
INSERT INTO twin.model_versions(id,organization_id,model_id,version,schema_version,ir,hash,created_by)
  VALUES ('mv_01M4YDQK00TA00000000000001','org_01M4YDQK00TA00000000000000','mdl_01M4YDQK00TA00000000000001',1,'0.1','{"constraints":[],"domain":"software_delivery","entity_types":[{"id":"change","name":"Change"}],"flows":[{"from":"start","id":"start_work","routing":{"probability":1,"type":"probability"},"to":"work"},{"from":"work","id":"work_end","routing":{"probability":1,"type":"probability"},"to":"end"}],"metrics":[],"model_id":"mdl_01M4YDQK00TA00000000000001","name":"Model A v1","nodes":[{"arrival":{"distribution":{"type":"constant","value":10},"max_entities":1},"entity_type":"change","id":"start","type":"source"},{"id":"work","requires":[{"resource_id":"worker","units":1}],"service_time":{"distribution":{"type":"constant","value":1}},"type":"process"},{"id":"end","type":"sink"}],"resources":[{"capacity":1,"id":"worker","name":"Worker","queue_discipline":"fifo","type":"human"}],"schema_version":"0.1","time_unit":"minute","views":{"2d":{},"3d":{}}}','sha256:432750f646ba93a763271505eaf1daa556ef60f2b8d7c97999529683c226120e','usr_01M4YDQK00TA00000000000001');

-- The API uploads: imports start as UPLOADED, each with one profile job.
SET LOCAL ROLE twin_api;
INSERT INTO twin.imports(id,organization_id,project_id,model_id,base_version_id,kind,filename,upload_object_key,upload_content_hash,size_bytes,status,created_by)
  SELECT i,'org_01M4YDQK00TA00000000000000','prj_01M4YDQK00TA00000000000001','mdl_01M4YDQK00TA00000000000001','mv_01M4YDQK00TA00000000000001','csv_events','原始資料.csv','tenant/org_01M4YDQK00TA00000000000000/imports/'||i||'/upload','sha256:1111111111111111111111111111111111111111111111111111111111111111',10,'UPLOADED','usr_01M4YDQK00TA00000000000001'
  FROM unnest(ARRAY['imp_01M4YDQK00TA00000000000003','imp_01M4YDQK00TA00000000000004','imp_01M4YDQK00TA00000000000005','imp_01M4YDQK00TA00000000000006']) AS i;
INSERT INTO twin.jobs(id,organization_id,type,status,payload,import_id)
  VALUES ('job_01M4YDQK00TA00000000000021','org_01M4YDQK00TA00000000000000','import_profile','queued','{"import_id":"imp_01M4YDQK00TA00000000000003"}','imp_01M4YDQK00TA00000000000003'),
         ('job_01M4YDQK00TA00000000000022','org_01M4YDQK00TA00000000000000','import_profile','queued','{"import_id":"imp_01M4YDQK00TA00000000000004"}','imp_01M4YDQK00TA00000000000004');
-- An import starts UPLOADED.
SELECT pg_temp.must_fail($q$INSERT INTO twin.imports(id,organization_id,project_id,model_id,base_version_id,kind,filename,upload_object_key,upload_content_hash,size_bytes,status,created_by)
  VALUES ('imp_01M4YDQK00TA00000000000009','org_01M4YDQK00TA00000000000000','prj_01M4YDQK00TA00000000000001','mdl_01M4YDQK00TA00000000000001','mv_01M4YDQK00TA00000000000001','csv_events','a.csv','tenant/org_01M4YDQK00TA00000000000000/imports/imp_01M4YDQK00TA00000000000009/upload','sha256:1111111111111111111111111111111111111111111111111111111111111111',10,'PROFILING','usr_01M4YDQK00TA00000000000001')$q$, '55000');

-- The API never writes what profiling finds, and does not move an import
-- while it is profiled: its job does.
SELECT pg_temp.must_fail(pg_temp.upd('imp_01M4YDQK00TA00000000000003', s), '55000') FROM unnest(ARRAY[
  $q$preview='[{"a":"1"}]'$q$,
  $q$error_report_object_key='tenant/org_01M4YDQK00TA00000000000000/imports/imp_01M4YDQK00TA00000000000003/e.csv', error_report_content_hash='sha256:2222222222222222222222222222222222222222222222222222222222222222', error_report_size_bytes=10$q$,
  $q$status='FAILED', error='{"code":"X","message":"x","retryable":false}'$q$,
  $q$status='PROFILING'$q$
]) AS s;
-- Nor the upload itself, which no role ever changes.
SELECT pg_temp.must_fail(pg_temp.upd('imp_01M4YDQK00TA00000000000003', s), '55000') FROM unnest(ARRAY[
  $q$filename='other.csv'$q$,
  $q$kind='json_events'$q$,
  $q$upload_object_key='tenant/org_01M4YDQK00TA00000000000000/imports/imp_01M4YDQK00TA00000000000004/upload'$q$,
  $q$upload_content_hash='sha256:2222222222222222222222222222222222222222222222222222222222222222'$q$,
  $q$size_bytes=11$q$,
  $q$base_version_id='mv_01M4YDQK00TA00000000000002'$q$,
  $q$created_by='usr_01M4YDQK00TA00000000000002'$q$,
  $q$created_at=created_at-interval '1 second'$q$
]) AS s;
-- The worker has no INSERT on imports.
SET LOCAL ROLE twin_worker;
SELECT pg_temp.must_fail($q$INSERT INTO twin.imports(id,organization_id,project_id,model_id,base_version_id,kind,filename,upload_object_key,upload_content_hash,size_bytes,status,created_by)
  VALUES ('imp_01M4YDQK00TA00000000000009','org_01M4YDQK00TA00000000000000','prj_01M4YDQK00TA00000000000001','mdl_01M4YDQK00TA00000000000001','mv_01M4YDQK00TA00000000000001','csv_events','a.csv','tenant/org_01M4YDQK00TA00000000000000/imports/imp_01M4YDQK00TA00000000000009/upload','sha256:1111111111111111111111111111111111111111111111111111111111111111',10,'UPLOADED','usr_01M4YDQK00TA00000000000001')$q$, '42501');

-- A profile exists exactly when the import is past profiling.
SELECT pg_temp.must_fail(pg_temp.upd('imp_01M4YDQK00TA00000000000003', s), '23514') FROM unnest(ARRAY[
  $q$profile='{"format":"csv","encoding":"utf-8","rows":0,"columns":[]}'$q$,
  $q$status='PROFILING', profile='{"format":"csv","encoding":"utf-8","rows":0,"columns":[]}'$q$,
  $q$status='AWAITING_MAPPING'$q$,
  $q$status='FAILED'$q$
]) AS s;
-- The worker profiles: PROFILING, then AWAITING_MAPPING with the profile,
-- the preview, the counts and the error report, all through its column
-- grants (D-037).
UPDATE twin.imports SET status='PROFILING' WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000003';
-- A profile is a JSON object; an error report is named by key, hash and
-- size together, within 16 MiB, under the tenant's imports prefix (D-035).
SELECT pg_temp.must_fail(pg_temp.upd('imp_01M4YDQK00TA00000000000003', s), '23514') FROM unnest(ARRAY[
  $q$status='AWAITING_MAPPING', profile='[]'$q$,
  $q$status='AWAITING_MAPPING', profile='{}', error_report_object_key='tenant/org_01M4YDQK00TA00000000000000/imports/imp_01M4YDQK00TA00000000000003/e.csv'$q$,
  $q$status='AWAITING_MAPPING', profile='{}', error_report_object_key='tenant/org_01M4YDQK00TA00000000000000/imports/imp_01M4YDQK00TA00000000000003/e.csv', error_report_content_hash='sha256:2222222222222222222222222222222222222222222222222222222222222222'$q$,
  $q$status='AWAITING_MAPPING', profile='{}', error_report_content_hash='sha256:2222222222222222222222222222222222222222222222222222222222222222', error_report_size_bytes=10$q$,
  $q$status='AWAITING_MAPPING', profile='{}', error_report_object_key='tenant/org_01M4YDQK00TA00000000000000/imports/imp_01M4YDQK00TA00000000000003/e.csv', error_report_content_hash='sha256:2222222222222222222222222222222222222222222222222222222222222222', error_report_size_bytes=0$q$,
  $q$status='AWAITING_MAPPING', profile='{}', error_report_object_key='tenant/org_01M4YDQK00TA00000000000000/imports/imp_01M4YDQK00TA00000000000003/e.csv', error_report_content_hash='sha256:2222222222222222222222222222222222222222222222222222222222222222', error_report_size_bytes=16777217$q$,
  $q$status='AWAITING_MAPPING', profile='{}', error_report_object_key='tenant/org_01M4YDQK00TB00000000000000/imports/imp_01M4YDQK00TA00000000000003/e.csv', error_report_content_hash='sha256:2222222222222222222222222222222222222222222222222222222222222222', error_report_size_bytes=10$q$,
  $q$status='AWAITING_MAPPING', profile='{}', error_report_object_key='tenant/orgX01M4YDQK00TA00000000000000/imports/imp_01M4YDQK00TA00000000000003/e.csv', error_report_content_hash='sha256:2222222222222222222222222222222222222222222222222222222222222222', error_report_size_bytes=10$q$,
  $q$status='AWAITING_MAPPING', profile='{}', error_report_object_key='tenant/org_01M4YDQK00TA00000000000000/simulation-results/imp_01M4YDQK00TA00000000000003/e.csv', error_report_content_hash='sha256:2222222222222222222222222222222222222222222222222222222222222222', error_report_size_bytes=10$q$,
  $q$status='AWAITING_MAPPING', profile='{}', error_report_object_key='tenant/org_01M4YDQK00TA00000000000000/imports/imp_01M4YDQK00TA00000000000003/../e.csv', error_report_content_hash='sha256:2222222222222222222222222222222222222222222222222222222222222222', error_report_size_bytes=10$q$
]) AS s;
UPDATE twin.imports SET status='AWAITING_MAPPING',
    profile='{"format":"csv","encoding":"utf-8-bom","rows":3,"columns":[{"name":"欄","index":0,"inferred":"integer","non_empty":2,"max_length":2}]}',
    preview='[{"欄":"1"},{"欄":"22"},{"欄":""}]', total_rows=3, invalid_rows=1,
    error_report_object_key='tenant/org_01M4YDQK00TA00000000000000/imports/imp_01M4YDQK00TA00000000000003/profile-errors-1.csv', error_report_content_hash='sha256:2222222222222222222222222222222222222222222222222222222222222222', error_report_size_bytes=120
  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000003';
SELECT pg_temp.check(status='AWAITING_MAPPING' AND profile->>'encoding'='utf-8-bom' AND preview->1->>'欄'='22' AND error_report_size_bytes=120,
    'the worker wrote the profile: '||status)
  FROM twin.imports WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000003';
-- The profile is written once, and a profiled import is never profiled
-- again, whoever asks.
SELECT pg_temp.must_fail(pg_temp.upd('imp_01M4YDQK00TA00000000000003', s), '55000') FROM unnest(ARRAY[
  $q$profile='{"format":"csv","encoding":"utf-8","rows":3,"columns":[]}'$q$,
  $q$status='PROFILING', profile=NULL$q$,
  $q$status='UPLOADED', profile=NULL$q$
]) AS s;
SET LOCAL ROLE twin_owner;
SELECT pg_temp.must_fail(pg_temp.upd('imp_01M4YDQK00TA00000000000003', s), '55000') FROM unnest(ARRAY[
  $q$profile='{"format":"csv","encoding":"utf-8","rows":3,"columns":[]}'$q$,
  $q$status='UPLOADED', profile=NULL, preview='[]', total_rows=0, invalid_rows=0$q$,
  $q$upload_content_hash='sha256:2222222222222222222222222222222222222222222222222222222222222222'$q$,
  $q$filename='renamed.csv'$q$
]) AS s;
-- The API still keeps the human-confirmed columns of a profiled import
-- (T-017) but never touches its profile, preview or error report.
SET LOCAL ROLE twin_api;
UPDATE twin.imports SET mapping='{"mappings":[]}', mapping_revision=mapping_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000003';
SELECT pg_temp.must_fail(pg_temp.upd('imp_01M4YDQK00TA00000000000003', s), '55000') FROM unnest(ARRAY[
  $q$preview='[]'$q$,
  $q$error_report_object_key=NULL, error_report_content_hash=NULL, error_report_size_bytes=NULL$q$
]) AS s;

-- A file that cannot be profiled: FAILED with its error, and final.
SET LOCAL ROLE twin_worker;
UPDATE twin.imports SET status='PROFILING' WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000004';
UPDATE twin.imports SET status='FAILED', error='{"code":"JSON_DUPLICATE_KEY","message":"duplicate object member name","path":"/41/case_id","retryable":false}'
  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000004';
SELECT pg_temp.must_fail(pg_temp.upd('imp_01M4YDQK00TA00000000000004', s), '55000') FROM unnest(ARRAY[
  $q$status='PROFILING', error=NULL$q$,
  $q$error='{"code":"X","message":"x","retryable":true}'$q$
]) AS s;
SET LOCAL ROLE twin_api;
SELECT pg_temp.must_fail(pg_temp.upd('imp_01M4YDQK00TA00000000000004', $q$mapping='{"mappings":[]}'$q$), '55000');
SET LOCAL ROLE twin_owner;
SELECT pg_temp.must_fail(pg_temp.upd('imp_01M4YDQK00TA00000000000004', s), '55000') FROM unnest(ARRAY[
  $q$status='UPLOADED', error=NULL$q$,
  $q$error='{"code":"X","message":"x","retryable":true}'$q$
]) AS s;

-- The owner moves an import only the ways the checks allow: from
-- UPLOADED straight to FAILED (an operator ending a stuck upload), never to
-- AWAITING_MAPPING without a profile.
SELECT pg_temp.must_fail(pg_temp.upd('imp_01M4YDQK00TA00000000000005', $q$status='AWAITING_MAPPING'$q$), '23514');
UPDATE twin.imports SET status='FAILED', error='{"code":"OPERATOR","message":"ended by an operator","retryable":false}'
  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000005';
-- An unchanged row is no change.
SET LOCAL ROLE twin_api;
UPDATE twin.imports SET filename=filename WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000006';

-- Any other role is refused whatever privileges it is given.
RESET ROLE;
GRANT SELECT, UPDATE ON twin.imports TO twin_provisioner;
SET LOCAL ROLE twin_provisioner;
SELECT pg_temp.must_fail(pg_temp.upd('imp_01M4YDQK00TA00000000000006', $q$status='PROFILING'$q$), '55000');
RESET ROLE;
REVOKE SELECT, UPDATE ON twin.imports FROM twin_provisioner;
SET LOCAL ROLE twin_owner;
SELECT pg_temp.check(string_agg(status, ',' ORDER BY id)='AWAITING_MAPPING,FAILED,FAILED,UPLOADED', 'the imports ended as they did: '||string_agg(status, ',' ORDER BY id))
  FROM twin.imports WHERE organization_id='org_01M4YDQK00TA00000000000000';

ROLLBACK;
